  yAxis: { type: 'value', min: 0, splitNumber: 3, axisLabel: { color: muted, fontSize: 11, formatter: (v) => Number(v).toLocaleString('en-US') }, splitLine: { lineStyle: { color: 'rgba(128,128,128,0.15)' } } },
  series: [{
    type: 'line', name: 'Patients with BP <140/90', data: pts.length > 1 ? pts.slice(0, -1) : pts, showSymbol: true, symbolSize: 5,
    lineStyle: { color: green, width: 2 }, itemStyle: { color: green },
    areaStyle: { color: { type: 'linear', x: 0, y: 0, x2: 0, y2: 1, colorStops: [{ offset: 0, color: 'rgba(59,178,49,0.22)' }, { offset: 1, color: 'rgba(59,178,49,0.03)' }] } },
    markPoint: last ? { symbol: 'circle', symbolSize: 9, itemStyle: { color: green }, label: { show: false }, data: [{ coord: last }] } : undefined
  }, {
