options.styles:
.coh { display: flex; flex-direction: column; justify-content: space-between; height: 100%; font-size: 13px; line-height: 1.3; }
.coh-row { display: flex; gap: 12px; padding: 8px 4px 0 4px; overflow-x: auto; }
.coh-q { flex: 1 1 0; min-width: 104px; max-width: 136px; display: flex; flex-direction: column; align-items: center; text-align: center; gap: 8px; }
.coh-bar { height: 250px; width: 56px; display: flex; flex-direction: column; gap: 2px; border-radius: 4px; overflow: hidden; }
.seg { display: flex; align-items: center; justify-content: center; line-height: 1; color: #fff; font-weight: 700; font-size: 13px; text-shadow: 0 1px 3px rgba(0,0,0,0.3); }
.coh-detail { display: flex; flex-direction: column; font-size: 13px; }
.coh-detail b { white-space: nowrap; }
.coh-note { margin-top: 6px; font-size: 11px; color: #888; }
.coh-key { display: flex; justify-content: flex-end; gap: 16px; padding: 8px 4px 2px 4px; font-size: 12px; }
.coh-key span { display: flex; align-items: center; gap: 6px; }
.coh-key i { display: inline-block; width: 14px; height: 14px; border-radius: 3px; }
.coh-controlled { background: #3bb231; }
.coh-uncontrolled { background: #eeab00; }
.coh-novisit { background: #ed6300; }

