options.styles:
.stc { display: flex; height: 100%; font-size: 13px; line-height: 1.3; padding: 4px 4px 0 4px; }
.stc-col { flex: 1 1 0; min-width: 0; display: flex; flex-direction: column; }
.stc-divider { width: 1px; background: rgba(128,128,128,0.25); margin: 0 24px; }
.stc-rows { flex: 1 1 auto; display: flex; flex-direction: column; justify-content: center; gap: 16px; }
.stc-row { display: grid; grid-template-columns: 136px 1fr 72px; align-items: center; column-gap: 12px; }
.stc-row-target { padding-bottom: 18px; }
.stc-label { font-size: 13px; }
.stc-caption { grid-column: 1 / -1; font-size: 12px; color: #6e7f8d; margin-top: 4px; }
