  }
});
const dayLabel = (ms) => { const d = new Date(ms); return d.getUTCDate() + '-' + months[d.getUTCMonth()] + '-' + d.getUTCFullYear(); };
const winOf = (ms) => { const e = new Date(ms); return [Date.UTC(e.getUTCFullYear(), e.getUTCMonth() - 2, 1), Date.UTC(e.getUTCFullYear(), e.getUTCMonth() + 1, 0)]; };
const pctOf = (vals, den, i) => { const dn = Number(den[i]) || 0; return dn ? 100 * (Number(vals[i]) || 0) / dn : null; };
const pctTxt = (p) => p === null ? '–' : Math.round(p) + '%';
const W = (context.panel.chart && context.panel.chart.getWidth && context.panel.chart.getWidth()) || 1200;
const lines = (t, width, px) => Math.max(1, Math.ceil(t.length * px / width));
const ctl = col('controlled_n');
const mod = col('moderate_n');
const high = col('high_n');
const nov = col('no_visit_n');
const den = col('denominator_n');
const green = '#3bb231';
const amber = '#eeab00';
const amberDark = '#c08b00';
// Not-controlled chart colours, exactly as hearts360 js/charts.js (dmUncontrolledData).
const uncTotalLine = '#D19600';
const uncHighBar = 'rgba(249,191,45,0.8)';
const uncModBar = 'rgba(244,212,128,0.6)';
const orange = '#ed6300';
const colW = W / 3;
const TITLES = ['Blood sugar controlled at latest visit in past 3 months', 'Blood sugar not controlled at latest visit in past 3 months', 'No visit in past 3 months'];
// Titles and the two uncontrolled lines wrap on narrow screens; push content down when they do.
const titleShift = TITLES.some((t) => lines(t, colW - 36, 7.8) > 1) ? 18 : 0;
const graphic = [];
let detailExtra = 0;
if (done !== undefined) {
  const [ws, we] = winOf(T[done]);
  graphic.push({ type: 'text', left: 12, top: 0, style: { text: 'Outcomes for ' + fmt(den[done]) + ' patients under care (registered before ' + dayLabel(ws) + ') between ' + dayLabel(ws) + ' to ' + dayLabel(we), fontSize: 13, fill: fg, width: W - 24, overflow: 'truncate' } });
  const modLine = fmt(mod[done]) + ' patients with FBS 126–199 mg/dL or HbA1c 7–8.9%';
  const highLine = fmt(high[done]) + ' patients with FBS ≥200 mg/dL or HbA1c ≥9%';
  const modRows = lines(modLine + '00%  ', colW - 36, 6.2);
  const highRows = lines(highLine + '00%  ', colW - 36, 6.2);
  detailExtra = Math.max(0, (modRows + highRows - 2) * 18);
  const t = (text, color) => ({ type: 'text', style: { text: text, fontSize: 14, fontWeight: 600, fill: color, width: colW - 36, overflow: 'break', lineHeight: 18 } });
  const big = (text, color) => ({ type: 'text', top: 26 + titleShift, style: { text: text, fontSize: 30, fontWeight: 700, fill: color } });
  const detail = (text) => ({ type: 'text', top: 64 + titleShift, style: { text: text, fontSize: 13, fill: fg, width: colW - 36, overflow: 'break' } });
  const figLine = (top, pct, color, text) => ({ type: 'text', top: top, style: { text: '{a|' + pct + '}  ' + text, fontSize: 13, fill: fg, width: colW - 36, overflow: 'break', lineHeight: 18, rich: { a: { fontSize: 18, fontWeight: 700, fill: color } } } });
  graphic.push({ type: 'group', left: 12, top: 32, children: [
    t(TITLES[0], green), big(pctTxt(pctOf(ctl, den, done)), green),
    detail(fmt(ctl[done]) + ' patients with RBS <140, FBS <126 mg/dL or HbA1c <7%') ] });
  graphic.push({ type: 'group', left: colW + 12, top: 32, children: [
    t(TITLES[1], amber),
    figLine(30 + titleShift, pctTxt(pctOf(mod, den, done)), amber, modLine),
    figLine(30 + titleShift + modRows * 18 + 8, pctTxt(pctOf(high, den, done)), amberDark, highLine) ] });
  graphic.push({ type: 'group', left: 2 * colW + 12, top: 32, children: [
