    detail(fmt(nov[done]) + ' patients with no visit') ] });
}
const top = 136 + titleShift + detailExtra;
const grid = [0, 1, 2].map((k) => ({ left: k * colW + 12, width: colW - 36, top: top, bottom: 14, containLabel: true }));
const xAxis = [0, 1, 2].map((k) => Object.assign({}, axisX, { gridIndex: k }));
const yAxis = [0, 1, 2].map((k) => ({ type: 'value', gridIndex: k, min: 0, max: 100, interval: 25, axisLabel: { color: muted, fontSize: 11, formatter: (v) => v + '%' }, splitLine: { lineStyle: { color: 'rgba(128,128,128,0.15)' } } }));
const series = [];
const trend = (k, name, color, fill, vals) => {
  const p = order.map((i) => pctOf(vals, den, i));
  series.push({ type: 'line', name: name, xAxisIndex: k, yAxisIndex: k, data: order.map((i, n) => [T[i], n < order.length - 1 ? p[n] : null]), showSymbol: true, symbolSize: 5, lineStyle: { color: color, width: 2 }, itemStyle: { color: color }, areaStyle: { color: fill } });
  series.push({ type: 'line', name: name, xAxisIndex: k, yAxisIndex: k, data: order.map((i, n) => [T[i], n >= order.length - 2 ? p[n] : null]), showSymbol: true, symbolSize: 5, lineStyle: { color: color, width: 2, type: 'dashed' }, itemStyle: { color: color } });
};
trend(0, TITLES[0], green, 'rgba(59,178,49,0.12)', ctl);
// Not controlled: stacked bars (high under moderate), the running month faded, as hearts360.
const bars = (name, color, vals) => ({ type: 'bar', name: name, stack: 'unc', xAxisIndex: 1, yAxisIndex: 1, barMaxWidth: 12,
  data: order.map((i, n) => ({ value: [T[i], pctOf(vals, den, i)], itemStyle: { color: color, opacity: n === order.length - 1 ? 0.45 : 1 } })) });
series.push(bars('FBS ≥200 mg/dL or HbA1c ≥9%', uncHighBar, high));
series.push(bars('FBS 126–199 mg/dL or HbA1c 7–8.9%', uncModBar, mod));
const uncTotal = mod.map((v, i) => (Number(v) || 0) + (Number(high[i]) || 0));
trend(1, 'Blood sugar not controlled (total)', uncTotalLine, 'rgba(0,0,0,0)', uncTotal);
trend(2, TITLES[2], orange, 'rgba(237,99,0,0.12)', nov);
return {
  animation: false,
  graphic: graphic,
  tooltip: tip((i, k) => shareRows([
    [['Blood sugar controlled', ctl[i]]],
    [['Blood sugar not controlled (total)', uncTotal[i], uncTotalLine],
     ['FBS \u2265200 mg/dL or HbA1c \u22659%', high[i], uncHighBar],
     ['FBS 126\u2013199 mg/dL or HbA1c 7\u20138.9%', mod[i], uncModBar]],
    [['No visit', nov[i]]]
