options.afterRender:
// Minimal XLSX writer: one sheet, bold frozen header, text and number cells, fitted widths.
// Self-contained (no library to load), so downloads work offline. An .xlsx file is a zip of
// a few XML parts; we store them uncompressed, which every spreadsheet app reads.
const makeXlsx = (sheetName, header, rows) => {
  const enc = new TextEncoder();
  const xml = (v) => String(v).replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f]/g, '')
    .replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
  const col = (i) => (i >= 26 ? col(Math.floor(i / 26) - 1) : '') + String.fromCharCode(65 + (i % 26));
  const cell = (v, ref, style) => (typeof v === 'number' && isFinite(v)
    ? '<c r="' + ref + '"' + style + '><v>' + v + '</v></c>'
    : '<c r="' + ref + '" t="inlineStr"' + style + '><is><t xml:space="preserve">' + xml(v == null ? '' : v) + '</t></is></c>');
  const all = [header].concat(rows);
  const widths = header.map((_, i) => Math.min(50, Math.max(8, ...all.map((r) => String(r[i] == null ? '' : r[i]).length + 2))));
  const NS = 'xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"';
  const REL = 'http://schemas.openxmlformats.org/officeDocument/2006/relationships';
  const files = {
    '[Content_Types].xml': '<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">'
      + '<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>'
      + '<Default Extension="xml" ContentType="application/xml"/>'
      + '<Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>'
      + '<Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>'
      + '<Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/></Types>',
    '_rels/.rels': '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
      + '<Relationship Id="rId1" Type="' + REL + '/officeDocument" Target="xl/workbook.xml"/></Relationships>',
    'xl/workbook.xml': '<workbook ' + NS + ' xmlns:r="' + REL + '"><sheets><sheet name="' + xml(sheetName.slice(0, 31)) + '" sheetId="1" r:id="rId1"/></sheets></workbook>',
    'xl/_rels/workbook.xml.rels': '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
      + '<Relationship Id="rId1" Type="' + REL + '/worksheet" Target="worksheets/sheet1.xml"/>'
      + '<Relationship Id="rId2" Type="' + REL + '/styles" Target="styles.xml"/></Relationships>',
    'xl/styles.xml': '<styleSheet ' + NS + '><fonts count="2"><font><sz val="11"/><name val="Calibri"/></font><font><b/><sz val="11"/><name val="Calibri"/></font></fonts>'
      + '<fills count="2"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill></fills>'
      + '<borders count="1"><border><left/><right/><top/><bottom/><diagonal/></border></borders>'
      + '<cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs>'
      + '<cellXfs count="2"><xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/><xf numFmtId="0" fontId="1" fillId="0" borderId="0" xfId="0" applyFont="1"/></cellXfs></styleSheet>',
    'xl/worksheets/sheet1.xml': '<worksheet ' + NS + '><sheetViews><sheetView workbookViewId="0"><pane ySplit="1" topLeftCell="A2" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews>'
      + '<cols>' + widths.map((w, i) => '<col min="' + (i + 1) + '" max="' + (i + 1) + '" width="' + w + '" customWidth="1"/>').join('') + '</cols><sheetData>'
      + all.map((r, ri) => '<row r="' + (ri + 1) + '">' + r.map((v, ci) => cell(v, col(ci) + (ri + 1), ri ? '' : ' s="1"')).join('') + '</row>').join('')
      + '</sheetData></worksheet>',
  };

  // Zip with "stored" entries: local headers + data, then the central directory.
  const crcTable = Array.from({ length: 256 }, (_, n) => { let c = n; for (let k = 0; k < 8; k++) { c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1; } return c >>> 0; });
  const crc32 = (b) => { let c = 0xffffffff; for (let i = 0; i < b.length; i++) { c = crcTable[(c ^ b[i]) & 0xff] ^ (c >>> 8); } return (c ^ 0xffffffff) >>> 0; };
  const u16 = (v) => [v & 0xff, (v >>> 8) & 0xff];
  const u32 = (v) => [v & 0xff, (v >>> 8) & 0xff, (v >>> 16) & 0xff, (v >>> 24) & 0xff];
  const parts = [], central = [];
  let offset = 0;
  Object.entries(files).forEach(([name, text]) => {
    const data = enc.encode('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n' + text);
    const nm = enc.encode(name), crc = crc32(data);
    const common = [].concat(u16(20), u16(0x0800), u16(0), u16(0), u16(0x21), u32(crc), u32(data.length), u32(data.length), u16(nm.length), u16(0));
    const local = Uint8Array.from([].concat(u32(0x04034b50), common));
    parts.push(local, nm, data);
    central.push(Uint8Array.from([].concat(u32(0x02014b50), u16(20), common, u16(0), u16(0), u16(0), u32(0), u32(offset))), nm);
    offset += local.length + nm.length + data.length;
  });
  const cdSize = central.reduce((s, b) => s + b.length, 0);
  const end = Uint8Array.from([].concat(u32(0x06054b50), u16(0), u16(0), u16(central.length / 2), u16(central.length / 2), u32(cdSize), u32(offset), u16(0)));
  return new Blob(parts.concat(central, [end]), { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
};

// Overdue list with an auto-saving status dropdown (hearts360 style).
// Runs as the Business Text panel's afterRender on one result set: patients, plus the status
// options and place name as columns (no options on the central node makes it read-only).
const root = context.element.querySelector('.ovq');
if (!root) { return; }

const series = (context.panelData && context.panelData.series) || [];
const rowsOf = (ref) => {
  const f = series.find((s) => s.refId === ref);
  if (!f) { return []; }
  const cols = f.fields.map((x) => [x.name, Array.from(x.values)]);
  const n = cols.length ? cols[0][1].length : 0;
  return Array.from({ length: n }, (_, i) => Object.fromEntries(cols.map(([k, v]) => [k, v[i]])));
};
// Row 1 always exists: it carries the facility-level and access flags; patients are the rest.
const all = rowsOf('A');
const flags = all[0] || {};
const rows = all.filter((r) => r.patient_id != null);
const options = String((rows[0] || {}).status_options || '').split('|').filter(Boolean);
const place = (rows[0] || {}).place || 'this place';

// Same rule as the table's update SQL: these keep the patient on the list; the rest remove them.
const ACTIVE = ['Pending to call', 'Agreed to visit', 'Call again later'];
const REMOVED = 'Removed from list';
// hearts360's lost-to-follow-up bucket: over a year since the last visit, whatever the call result.
const YEAR = 'No visit in 1 year';
const GROUPS = ACTIVE.concat(REMOVED, YEAR);
const PAGE = 20;
const DL_LABEL = 'Download list (XLSX)';
const byId = Object.fromEntries(rows.map((r) => [r.patient_id, r]));
// Opens on the call queue, as hearts360 does, most recently seen first (fewest days since last visit).
const state = { status: 'Pending to call', q: '', facility: '', phone: '', asc: true, page: 0 };

const esc = (v) => String(v == null ? '' : v).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const fmt = (n) => Number(n || 0).toLocaleString('en-US');
const today = () => { const d = new Date(); return d.getDate() + ' ' + d.toLocaleString('en-US', { month: 'short' }) + ', ' + d.getFullYear(); };
const lapsed = (r) => (r.days_since_last_visit || 0) > 365;
const groupOf = (r) => (lapsed(r) ? YEAR : ACTIVE.includes(r.removed_reason) ? r.removed_reason : REMOVED);
const TIP = {
  [YEAR]: "These patients haven't visited in over a year. Call them to bring them back to care.",
  default: 'Call patients, then choose their new overdue status. It saves automatically.',
};

const visible = () => {
  const q = state.q.trim().toLowerCase();
  return rows
    .filter((r) => state.status === 'All' || groupOf(r) === state.status)
    .filter((r) => !state.facility || r.facility === state.facility)
    .filter((r) => !state.phone || (String(r.phone_number || '').trim() !== '') === (state.phone === 'with'))
    .filter((r) => !q || [r.patient_name, r.patient_id, r.phone_number].some((v) => String(v || '').toLowerCase().includes(q)))
    .sort((a, b) => (state.asc ? 1 : -1) * ((a.days_since_last_visit || 0) - (b.days_since_last_visit || 0)));
};

// What the dropdown shows: never-contacted patients over a year out show "No visit in 1 year"
// (not selectable, never saved); everyone else shows their saved status.
const shownStatus = (r) => (lapsed(r) && r.never_contacted ? YEAR : r.removed_reason);

const statusCell = (r) => {
  const cur = shownStatus(r);
  if (!options.length) { return esc(cur); }
  const opt = (o) => '<option' + (o === cur ? ' selected' : '') + '>' + esc(o) + '</option>';
  const fixed = options.includes(cur) ? '' : '<option selected disabled>' + esc(cur) + '</option>';
  const removal = options.filter((o) => !ACTIVE.includes(o));
  return '<select class="ovq-sel" data-id="' + esc(r.patient_id) + '" data-cur="' + esc(cur) + '" aria-label="Overdue status for ' + esc(r.patient_name) + '">'
    + fixed + ACTIVE.filter((o) => options.includes(o)).map(opt).join('')
    + (removal.length ? '<optgroup label="Or, remove from list">' + removal.map(opt).join('') + '</optgroup>' : '')
    + '</select><div class="ovq-msg" aria-live="polite"></div>';
};

// [header, cell, optional class for alignment]
const pill = (c) => '<span class="ovq-pill ovq-pill-' + c.toLowerCase() + '">' + esc(c) + '</span>';
const COLS = [
  ['Overdue status', statusCell],
  ['Name', (r) => esc(r.patient_name) + '<div class="ovq-id">' + esc(r.patient_id) + '</div>'],
  ['Gender', (r) => esc(r.gender)],
  ['Age', (r) => esc(r.age_years), 'num'],
  ['Condition', (r) => String(r.conditions || '').split('|').filter(Boolean).map(pill).join(' '), 'nowrap'],
  ['Phone', (r) => esc(r.phone_number), 'nowrap'],
  ['Facility', (r) => esc(r.facility), 'nowrap'],
  ['HTN Diagnosis date', (r) => esc(r.registration_label)],
  ['Last visited on', (r) => esc(r.last_visit_label).replace(/\n/g, '<br><span class="ovq-soft">') + (String(r.last_visit_label || '').includes('\n') ? '</span>' : '')],
  ['Last BP', (r) => esc(r.last_bp), 'nowrap'],
  // Red only past 30 days.
  ['Days since last visit', (r) => '<span' + ((r.days_since_last_visit || 0) > 30 ? ' class="ovq-red"' : '') + '>' + fmt(r.days_since_last_visit) + '</span>', 'num'],
  ['Last contacted on', (r) => '<span class="ovq-lc">' + esc(r.last_contacted_label) + '</span>'],
];
const cls = (c) => (c ? ' class="' + c + '"' : '');

const renderCounts = () => {
  const n = (g) => rows.filter((r) => groupOf(r) === g).length;
  root.querySelector('.ovq-chips').innerHTML = [['All', rows.length]].concat(GROUPS.map((g) => [g, n(g)]))
    .map(([g, c]) => '<button type="button" class="ovq-chip' + (state.status === g ? ' on' : '') + '" data-status="' + esc(g) + '">' + esc(g) + ': ' + fmt(c) + '</button>')
    .join('');
};

const renderBody = () => {
  const list = visible();
  const pages = Math.max(1, Math.ceil(list.length / PAGE));
  state.page = Math.min(state.page, pages - 1);
  const shown = list.slice(state.page * PAGE, (state.page + 1) * PAGE);
  root.querySelector('tbody').innerHTML = shown.length
    ? shown.map((r) => '<tr data-id="' + esc(r.patient_id) + '">' + COLS.map(([, cell, c]) => '<td' + cls(c) + '>' + cell(r) + '</td>').join('') + '</tr>').join('')
    : '<tr><td class="ovq-empty" colspan="' + COLS.length + '">No patients match these filters.</td></tr>';
  root.querySelector('.ovq-sort').textContent = state.asc ? '↑' : '↓';
  root.querySelector('.ovq-pager').innerHTML = list.length
    ? '<button type="button" data-page="-1"' + (state.page ? '' : ' disabled') + ' aria-label="Previous page">‹</button>'
      + '<span>' + fmt(state.page * PAGE + 1) + '–' + fmt(state.page * PAGE + shown.length) + ' of ' + fmt(list.length) + '</span>'
      + '<button type="button" data-page="1"' + (state.page < pages - 1 ? '' : ' disabled') + ' aria-label="Next page">›</button>'
    : '';
  if (options.length) { root.querySelector('.ovq-tip').textContent = TIP[state.status] || TIP.default; }
  root.querySelector('.ovq-dl').disabled = !list.length;
  renderCounts();
};

// Same warnings (and wording) as the old warning strip above the list.
const warn = (html) => '<div class="ovq-warn"><span>\u26a0\ufe0f</span><span>' + html + '</span></div>';
if (Number(flags.isAccessible) === 0) {
  root.innerHTML = warn('<strong>Overdue patient list is available only at the facility and sub-facility levels.</strong>');
  return;
}
if (Number(flags.isAllowed) === 0) {
  root.innerHTML = warn('<strong>Access Denied:</strong> Ask admin to add to one of these teams: ' + (flags.requiredGroups || ''));
  return;
}
if (!rows.length) { root.innerHTML = '<h2 class="ovq-title">Overdue patients</h2><div class="ovq-head">No overdue patients to show.</div>'; return; }

const facilities = [...new Set(rows.map((r) => r.facility).filter(Boolean))].sort();
// Header as hearts360: title, "3,250 overdue patients in River District", then a download link.
root.innerHTML = '<h2 class="ovq-title">Overdue patients</h2>'
  + '<div class="ovq-head">' + fmt(rows.length) + ' overdue patients in ' + esc(place) + '</div>'
  + '<button type="button" class="ovq-dl" data-download="1">' + DL_LABEL + '</button>'
  + '<div class="ovq-chips" role="group" aria-label="Filter by overdue status"></div>'
  + '<div class="ovq-tip">' + (options.length
    ? TIP.default
    : 'Overdue status can only be changed on the facility dashboard.') + '</div>'
  + '<div class="ovq-tools"><input type="search" class="ovq-q" placeholder="Search name, Patient ID or phone" aria-label="Search patients">'
  + (facilities.length > 1 ? '<select class="ovq-fac" aria-label="Facility"><option value="">All facilities</option>' + facilities.map((f) => '<option>' + esc(f) + '</option>').join('') + '</select>' : '')
  + '<select class="ovq-phone" aria-label="Phone"><option value="">All patients</option><option value="with">With phone</option><option value="without">Without phone</option></select>'
  + '</div><div class="ovq-wrap"><table><thead><tr>'
  + COLS.map(([h, , c]) => (h === 'Days since last visit'
    ? '<th' + cls(c) + '><button type="button" class="ovq-sortbtn" data-sort="1">' + h + ' <span class="ovq-sort"></span></button></th>'
    : '<th' + cls(c) + '>' + h + '</th>')).join('')
  + '</tr></thead><tbody></tbody></table></div><div class="ovq-pager"></div>';
renderBody();

// --- Saving: posted to h360-api, which takes identity from the Grafana session.
const H360_API = location.protocol + '//' + location.hostname + ':8090';
const save = async (pid, reason) => {
  if (!/^\d+$/.test(pid) || !options.includes(reason)) { throw new Error('Unexpected value'); }
  const body = JSON.stringify({ patient_id: String(pid), status: reason });
  const res = await fetch(H360_API + '/write/call-result', {method:'POST', credentials:'include', headers:{'Content-Type':'application/json','X-H360-Request':'1'}, body});
  const saved = await res.json().catch(() => ({}));
  const err = res.ok && saved.ok !== false ? '' : (saved.message || res.statusText);
  if (err) { throw new Error(err); }
};

const message = (sel, html, cls) => { const m = sel.parentElement.querySelector('.ovq-msg'); m.className = 'ovq-msg ' + (cls || ''); m.innerHTML = html; };

const commit = async (sel, r, next) => {
  sel.disabled = true;
  message(sel, 'Saving…');
  try {
    await save(r.patient_id, next);
    r.removed_reason = next;
    r.never_contacted = false;
    sel.dataset.cur = next;
    r.last_contacted_label = today();
    sel.closest('tr').querySelector('.ovq-lc').textContent = r.last_contacted_label;
    message(sel, 'Saved ✓', 'ok');
    renderCounts();
    // Fade only the "Saved" note; never wipe a newer prompt (e.g. a removal confirmation).
    setTimeout(() => { const m = sel.parentElement && sel.parentElement.querySelector('.ovq-msg.ok'); if (m) { message(sel, ''); } }, 2500);
  } catch (e) {
    sel.value = sel.dataset.cur;
    message(sel, "Couldn't save. Try again.", 'err');
    context.grafana.notifyError(["Couldn't save overdue status", e.message]);
  } finally {
    sel.disabled = false;
  }
};

// --- Download: everything the current chip, search and facility filter show (all pages).
const XLSX_COLS = [
  ['Overdue status', (r) => shownStatus(r)],
  ['Name', (r) => r.patient_name],
  ['Patient ID', (r) => String(r.patient_id)],  // text, so long IDs aren't rounded
  ['Gender', (r) => r.gender],
  ['Age', (r) => (r.age_years == null ? '' : Number(r.age_years))],
  ['Condition', (r) => String(r.conditions || '').split('|').filter(Boolean).join(', ')],
  ['Phone', (r) => (r.phone_number == null ? '' : String(r.phone_number))],
  ['Facility', (r) => r.facility],
  ['HTN Diagnosis date', (r) => r.registration_label],
  ['Last visited on', (r) => String(r.last_visit_label || '').replace(/\n/g, ' ')],
  ['Last BP', (r) => r.last_bp],
  ['Days since last visit', (r) => (r.days_since_last_visit == null ? '' : Number(r.days_since_last_visit))],
  ['Last contacted on', (r) => r.last_contacted_label],
];
const download = (btn) => {
  const list = visible();
  const blob = makeXlsx('Overdue patients', XLSX_COLS.map(([h]) => h), list.map((r) => XLSX_COLS.map(([, f]) => f(r))));
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = 'Overdue patients - ' + place + (state.status === 'All' ? '' : ' - ' + state.status) + ' - ' + today().replace(',', '') + '.xlsx';
  a.click();  // detached on purpose: an attached link is caught by Grafana's link handling
  setTimeout(() => URL.revokeObjectURL(a.href), 1000);
  btn.textContent = 'Downloaded \u2713';
  setTimeout(() => { btn.textContent = DL_LABEL; }, 2000);
};

root.addEventListener('change', (e) => {
  if (e.target.classList.contains('ovq-fac')) { state.facility = e.target.value; state.page = 0; renderBody(); return; }
  if (e.target.classList.contains('ovq-phone')) { state.phone = e.target.value; state.page = 0; renderBody(); return; }
  const sel = e.target.closest('.ovq-sel');
  if (!sel) { return; }
  const r = byId[sel.dataset.id];
  const next = sel.value;
  if (ACTIVE.includes(next)) { commit(sel, r, next); return; }
  // Removal reasons take the patient off the list, so ask first.
  sel.disabled = true;
  message(sel, 'Remove from list? Reason: ' + esc(next)
    + ' <button type="button" class="ovq-yes">Remove</button> <button type="button" class="ovq-no">Cancel</button>', 'ask');
});

root.addEventListener('input', (e) => {
  if (e.target.classList.contains('ovq-q')) { state.q = e.target.value; state.page = 0; renderBody(); }
});

root.addEventListener('click', (e) => {
  const b = e.target.closest('button');
  if (!b) { return; }
  if (b.dataset.status) { state.status = b.dataset.status; state.page = 0; renderBody(); return; }
  if (b.dataset.page) { state.page += Number(b.dataset.page); renderBody(); return; }
  if (b.dataset.sort) { state.asc = !state.asc; renderBody(); return; }
  if (b.dataset.download) { download(b); return; }
  const sel = b.closest('td') && b.closest('td').querySelector('.ovq-sel');
  if (!sel) { return; }
  const r = byId[sel.dataset.id];
  if (b.classList.contains('ovq-yes')) { commit(sel, r, sel.value); }
  if (b.classList.contains('ovq-no')) { sel.value = sel.dataset.cur; sel.disabled = false; message(sel, ''); sel.focus(); }
});

options.styles:
.ovq { font-size: 13px; line-height: 1.35; }
/* Header as hearts360: bold title, plain subtitle, blue text link to download. */
.ovq-title { font-size: 22px; font-weight: 700; margin: 0 0 4px; line-height: 1.25; }
.ovq-head { font-size: 14px; margin: 0 0 8px; }
.ovq-dl { font: inherit; font-size: 14px; background: none; border: 0; padding: 0; margin: 0 0 14px; color: #0075eb; cursor: pointer; }
.ovq-dl:hover:not(:disabled) { text-decoration: underline; }
.ovq-dl:disabled { opacity: 0.45; cursor: default; }
.ovq-chips { display: flex; flex-wrap: wrap; gap: 6px; margin-bottom: 8px; }
.ovq-chip { border: 1px solid #d9e3ff; background: transparent; color: inherit; border-radius: 14px; padding: 2px 10px; font-size: 12px; cursor: pointer; }
.ovq-chip.on { background: #0075eb; border-color: #0075eb; color: #fff; }
.ovq-tip { background: LightGoldenrodYellow; color: rgba(0,0,0,0.7); padding: 6px 10px; border-radius: 4px; margin-bottom: 8px; }
.ovq-tools { display: flex; gap: 8px; margin-bottom: 10px; }
/* Inputs: hearts360's light border on white. Grafana's text styles squash native selects, so
   they also get a real height. */
.ovq select, .ovq input { font: inherit; color: #1c1c1c; background: #fff; border: 1px solid #d9e3ff; border-radius: 4px;
  padding: 4px 6px; height: 30px; line-height: 1.2; box-sizing: border-box; }
.ovq-tools input { width: 280px; }
.ovq-wrap { overflow-x: auto; }

/* Table: no vertical lines or stripes, a thin rule between rows and a light header (hearts360). */
.ovq table { width: 100%; border-collapse: collapse; border: 0; }
.ovq table th, .ovq table td { border: 0 !important; border-bottom: 1px solid rgba(128,128,128,0.2) !important; padding: 10px 8px; text-align: left; }
.ovq table th { background: rgba(0,117,235,0.06); color: #6e7f8d; font-size: 12px; font-weight: 600; white-space: nowrap; vertical-align: bottom; }
.ovq table td { vertical-align: top; }
.ovq tbody tr:hover { background: rgba(0,117,235,0.04); }
.ovq table .num { text-align: right; font-variant-numeric: tabular-nums; }
.ovq table .nowrap { white-space: nowrap; }
.ovq-id { font-size: 12px; color: #6e7f8d; font-variant-numeric: tabular-nums; margin-top: 1px; }
.ovq-pill { display: inline-block; padding: 1px 8px; border-radius: 100px; font-size: 12px; color: #1c1c1c; white-space: nowrap; }
.ovq-pill-htn { background: lavender; }
.ovq-pill-dm { background: bisque; }

/* Fixed status column: messages and the removal prompt wrap under the dropdown instead of
   widening the column while they show. */
.ovq-sel { width: 200px; }
.ovq table td:first-child, .ovq table th:first-child { width: 216px; max-width: 216px; }
.ovq-sel:disabled { opacity: 0.6; }
.ovq-msg { font-size: 12px; margin-top: 3px; }
.ovq-msg.ok { color: #3bb231; }
.ovq-msg.err { color: red; }
.ovq-msg.ask button { font: inherit; font-size: 12px; padding: 1px 8px; border-radius: 4px; border: 1px solid #d9e3ff; background: #fff; color: #1c1c1c; cursor: pointer; margin-top: 3px; }
.ovq-msg.ask .ovq-yes { background: red; border-color: red; color: #fff; }
.ovq-sortbtn { font: inherit; font-weight: 600; background: none; border: 0; padding: 0; color: inherit; cursor: pointer; }
.ovq-red { color: red; }
.ovq-soft { opacity: 0.65; }
.ovq-empty { text-align: center; padding: 18px; opacity: 0.7; }
.ovq-pager { display: flex; justify-content: center; align-items: center; gap: 12px; padding: 10px 0 2px; }
.ovq-pager button { font: inherit; width: 28px; height: 26px; border-radius: 4px; border: 1px solid #d9e3ff; background: transparent; color: inherit; cursor: pointer; }
.ovq-pager button:disabled { opacity: 0.35; cursor: default; }
.ovq-warn { color: #e02424; background: rgba(224,36,36,0.05); border-left: 4px solid #e02424; padding: 8px 14px; font-size: 13px; display: flex; align-items: center; gap: 8px; border-radius: 2px; line-height: 1.4; }

options.getOption:
const frame = (context.panel.data.series || [])[0];
function col(n) { const f = frame && frame.fields.find((x) => x.name === n); if (!f) { return []; } return Array.from(f.values && f.values.buffer ? f.values.buffer : f.values); }
const tr = context.panel.data.timeRange;
const from = tr ? tr.from.valueOf() : -Infinity;
const to = tr ? tr.to.valueOf() : Infinity;
const months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
const mLabel = (ms) => { const d = new Date(ms); return months[d.getUTCMonth()] + '-' + d.getUTCFullYear(); };
const theme = context.grafana && context.grafana.theme;
const fg = (theme && theme.colors && theme.colors.text && theme.colors.text.primary) || '#1c1c1c';
const muted = '#6e7f8d';
const T = col('ref_month').map(Number);
const order = T.map((v, i) => i).filter((i) => T[i] >= from && T[i] <= to).sort((a, b) => T[a] - T[b]);
const done = order.length > 1 ? order[order.length - 2] : order[order.length - 1];
const solid = (vals) => order.map((i, k) => [T[i], k < order.length - 1 ? Number(vals[i]) || 0 : null]);
const dashed = (vals) => order.map((i, k) => [T[i], k >= order.length - 2 ? Number(vals[i]) || 0 : null]);
const axisX = { type: 'time', axisLabel: { color: muted, fontSize: 11, hideOverlap: true, formatter: (v) => mLabel(v) }, axisLine: { lineStyle: { color: 'rgba(128,128,128,0.4)' } }, splitLine: { show: false } };
const head = (big, color, line2, line3, rich) => [
  { type: 'text', left: 12, top: 2, style: { text: big, fontSize: 30, fontWeight: 700, fill: color } },
  { type: 'text', left: 12, top: 42, style: { text: line2, fontSize: 13, fill: fg } },
  { type: 'text', left: 12, top: 62, style: { text: line3, fontSize: 13, fill: muted, rich: rich } }
];
const fmt = (v) => Math.round(Number(v) || 0).toLocaleString('en-US');
const soft = (t) => '<span style="opacity:0.7">' + t + '</span>';
// Colour key for charts with more than one series. Like hearts360 (Chart.js), the colour sits on
// white with a 1px white border, so translucent series colours read the same as on the chart.
const dot = (c) => '<span style="display:inline-block;width:10px;height:10px;border-radius:2px;margin-right:6px;'
  + (c ? 'border:1px solid #fff;background:linear-gradient(' + c + ',' + c + '),#fff' : 'border:1px solid transparent') + '"></span>';
const pctStr = (v, d) => (Number(d) ? Math.round(100 * (Number(v) || 0) / Number(d)) : 0) + '%';
// "Label: 61%" over "3,901 of 6,523 patients"; several rows become "Label: 29%, 387 patients" over "of 1,352 patients"
// (an optional third item per row adds a colour key).
const shareRows = (rows, d) => rows.length === 1
  ? [rows[0][0] + ': ' + pctStr(rows[0][1], d), soft(fmt(rows[0][1]) + ' of ' + fmt(d) + ' patients')]
  : rows.map(([label, v, c]) => dot(c) + label + ': ' + pctStr(v, d) + ', ' + fmt(v) + ' patients').concat(soft('of ' + fmt(d) + ' patients'));
// Shared tooltip: the hovered month in bold (marked while still running), then rowsFor(monthIndex, gridIndex).
const tip = (rowsFor) => ({
  trigger: 'axis', backgroundColor: 'rgba(28,28,28,0.92)', borderWidth: 0, padding: [8, 12],
  textStyle: { color: '#fff', fontSize: 13 }, extraCssText: 'border-radius: 6px;',
  axisPointer: { lineStyle: { color: 'rgba(110,127,141,0.6)' } },
  formatter: (ps) => {
    const p = [].concat(ps)[0];
    const n = p ? order.findIndex((i) => T[i] === Number(p.axisValue)) : -1;
    if (n < 0) { return ''; }
    const running = order.length > 1 && n === order.length - 1;
    return '<b>' + mLabel(T[order[n]]) + (running ? ' (in progress)' : '') + '</b><br>' + rowsFor(order[n], p.axisIndex || 0).join('<br>');
  }
});
const ovd = col('overdue_n');
const phone = col('overdue_phone_n');
const calledOvd = col('called_overdue_n');
const called = col('called_n');
const back = col('returned_n');
const known = col('calls_recorded').map((v) => v === true || v === 1 || v === 't' || v === 'true');
const ratio = (n, d, i) => (known[i] && Number(d[i]) ? 100 * (Number(n[i]) || 0) / Number(d[i]) : null);
const W = (context.panel.chart && context.panel.chart.getWidth && context.panel.chart.getWidth()) || 1200;
const colW = W / 3;
// Titles wrap on narrow screens; push the figures and charts down by one line when any does.
const wrapped = (t) => t.length * 7.8 > colW - 36;
const noCalls = ['No calls recorded'];
const COLS = [
  { color: '#ed6300', fill: 'rgba(237,99,0,0.12)', title: 'Overdue at the start of the month', count: true,
    point: (i) => Number(phone[i]) || 0,
    big: (i) => fmt(phone[i]),
    detail: (i) => fmt(phone[i]) + ' of ' + fmt(ovd[i]) + ' overdue patients have a phone',
    rows: (i) => ['Overdue with a phone number: ' + fmt(phone[i]), soft('of ' + fmt(ovd[i]) + ' overdue patients')] },
  { color: '#007ee4', fill: 'rgba(0,126,228,0.12)', title: 'Overdue patients called',
    point: (i) => ratio(calledOvd, phone, i),
    big: (i) => (ratio(calledOvd, phone, i) === null ? '–' : Math.round(ratio(calledOvd, phone, i)) + '%'),
    detail: (i) => (known[i] ? fmt(calledOvd[i]) + ' of ' + fmt(phone[i]) + ' overdue patients were called' : 'No calls recorded this month'),
    rows: (i) => (known[i] ? shareRows([['Called', calledOvd[i]]], phone[i]) : noCalls) },
  { color: '#3bb231', fill: 'rgba(59,178,49,0.12)', title: 'Overdue patients that returned to care',
    point: (i) => ratio(back, called, i),
    big: (i) => (ratio(back, called, i) === null ? '–' : Math.round(ratio(back, called, i)) + '%'),
    detail: (i) => (known[i] ? fmt(back[i]) + ' of ' + fmt(called[i]) + ' called patients visited within 15 days' : 'No calls recorded this month'),
    rows: (i) => (known[i] ? shareRows([['Returned to care', back[i]]], called[i]) : noCalls) }
];
const shift = COLS.some((c) => wrapped(c.title)) ? 18 : 0;
const graphic = [];
// Next steps (story 7.9): the same place, and the month of the big numbers.
const repl = (v) => (context.grafana && context.grafana.replaceVariables ? String(context.grafana.replaceVariables(v) || '') : '');
const orgId = repl('${org_unit}').trim();
const atFacility = [3, 4, 10].includes(Number(repl('${selected_level}')) || 0);
const monthIso = (ms) => { const d = new Date(ms); return d.getUTCFullYear() + '-' + String(d.getUTCMonth() + 1).padStart(2, '0') + '-01'; };
const callsUrl = '/d/heart360_reports?var-org_unit=' + encodeURIComponent(orgId)
  + (done !== undefined ? '&var-reporting_month=' + monthIso(T[done]) : '') + '&-dtab=Overdue-calls';
const listUrl = '/d/heart360_showcase?var-org_unit=' + encodeURIComponent(orgId) + '&-dtab=Overdue-list';
const go = (url) => () => { if (context.grafana && context.grafana.locationService) { context.grafana.locationService.push(url); } else { window.location.assign(url); } };
const linkFill = (theme && theme.colors && theme.colors.text && theme.colors.text.link) || '#1f62e0';
// Above facility level the overdue list is empty, so only the Reports link shows.
const LINKS = [['See calls by facility →', callsUrl]].concat(atFacility ? [['Open the overdue list →', listUrl]] : []);
let linksW = 0;
LINKS.slice().reverse().forEach(([text, url]) => {
  graphic.push({ type: 'text', right: 12 + linksW, top: 0, cursor: 'pointer', onclick: go(url),
    style: { text: text, fontSize: 13, fontWeight: 600, fill: linkFill } });
  linksW += text.length * 7.2 + 20;
});
if (done !== undefined) {
  graphic.push({ type: 'text', left: 12, top: 0, style: { text: 'Patients overdue at the start of ' + mLabel(T[done]) + ', the calls made to them that month, and the visits within 15 days of a call', fontSize: 13, fill: fg, width: W - 36 - linksW, overflow: 'truncate' } });
  COLS.forEach((c, k) => {
    graphic.push({ type: 'group', left: k * colW + 12, top: 32, children: [
      { type: 'text', style: { text: c.title, fontSize: 14, fontWeight: 600, fill: c.color, width: colW - 36, overflow: 'break', lineHeight: 18 } },
      { type: 'text', top: 26 + shift, style: { text: c.big(done), fontSize: 30, fontWeight: 700, fill: c.color } },
      { type: 'text', top: 64 + shift, style: { text: c.detail(done), fontSize: 13, fill: fg, width: colW - 36, overflow: 'break', lineHeight: 17 } }
    ] });
  });
}
const grid = [], xAxis = [], yAxis = [], series = [];
COLS.forEach((c, k) => {
  grid.push({ left: k * colW + 12, width: colW - 36, top: 136 + shift, bottom: 14, containLabel: true });
  xAxis.push(Object.assign({}, axisX, { gridIndex: k }));
  yAxis.push(c.count
    ? { type: 'value', gridIndex: k, min: 0, splitNumber: 4, axisLabel: { color: muted, fontSize: 11, formatter: (v) => fmt(v) }, splitLine: { lineStyle: { color: 'rgba(128,128,128,0.15)' } } }
    : { type: 'value', gridIndex: k, min: 0, max: 100, interval: 25, axisLabel: { color: muted, fontSize: 11, formatter: (v) => v + '%' }, splitLine: { lineStyle: { color: 'rgba(128,128,128,0.15)' } } });
  const pts = order.map((i) => c.point(i));
  const solidPts = order.map((i, n) => [T[i], n < order.length - 1 ? pts[n] : null]);
  const dashPts = order.map((i, n) => [T[i], n >= order.length - 2 ? pts[n] : null]);
  series.push({ type: 'line', name: c.title, xAxisIndex: k, yAxisIndex: k, data: solidPts, showSymbol: true, symbolSize: 5, lineStyle: { color: c.color, width: 2 }, itemStyle: { color: c.color }, areaStyle: { color: c.fill } });
  series.push({ type: 'line', name: c.title, xAxisIndex: k, yAxisIndex: k, data: dashPts, showSymbol: true, symbolSize: 5, lineStyle: { color: c.color, width: 2, type: 'dashed' }, itemStyle: { color: c.color } });
});
return {
  animation: false,
  graphic: graphic,
  tooltip: tip((i, k) => COLS[k].rows(i)),
  grid: grid, xAxis: xAxis, yAxis: yAxis, series: series
};
